
function quotationDocumentRows(items){return items.map((x,i)=>{const lines=String(x.description||'').split('\n'),nested=(lines[0].startsWith('งานติดตั้งสถานี')||lines[0].startsWith('งานติดตั้งระบบ Solar Roof'))&&lines.includes('รายการย่อยที่ลูกค้าจะได้รับ'),details=nested?lines.slice(2):[],cellStyle=nested?'border-bottom:0;':'',main=`<tr><td class="center" style="${cellStyle}">${i+1}</td><td style="text-align:left;overflow-wrap:anywhere;${cellStyle}">${nested?'<b>'+esc(lines[0])+'</b><div style="margin-top:3px">รายการย่อยที่ลูกค้าจะได้รับ</div>':nl2br(x.description)}</td><td class="center" style="${cellStyle}">${Number(x.quantity).toLocaleString('th-TH')}</td><td class="center" style="${cellStyle}">${esc(x.unit)}</td><td class="num" style="${cellStyle}">${money(x.unitPrice)}</td><td class="num" style="${cellStyle}">${money(quotationLineAmount(x))}</td></tr>`;return main+details.map((line,j)=>{const match=line.match(/^(.*?)\s+—\s+([\d.,]+)\s+(.+)$/),text=match?match[1]:line,style='border-top:0;'+(j<details.length-1?'border-bottom:0;':'');return `<tr class="quotation-subitem"><td style="${style}"></td><td style="text-align:left;overflow-wrap:anywhere;${style}">${esc(text)}</td><td class="center" style="${style}">${match?esc(match[2]):''}</td><td class="center" style="${style}">${match?esc(match[3]):''}</td><td style="${style}"></td><td style="${style}"></td></tr>`}).join('')}).join('')}
function quotationTerms(q,preview=false){const sections=[['เงื่อนไข / ส่งมอบ',[q.paymentTerms,q.deliveryTerms].filter(Boolean).join(' · ')],['การรับประกัน',quotationWarrantyText(q.warrantyText)],['ขอบเขต / ข้อยกเว้น',q.scopeText]];return `<section style="width:100%;box-sizing:border-box;text-align:left;border:1px solid #aaa;padding:${preview?'2px 4px':'3px 6px'};font-size:${preview?'7px':'11px'};line-height:1.25;color:#171717;background:#fff">${sections.map(([title,text],i)=>`<div style="text-align:left;margin:0;padding:${preview?'1px':'2px'} 0;${i?'border-top:1px solid #ddd;':''}overflow-wrap:break-word;word-break:normal"><b style="display:inline;color:#111;white-space:nowrap">${title}:</b> ${esc(String(text||'').replace(/\s*\r?\n\s*/g,' ').trim()).replace(/ระยะ\s*ดำเนินการ/g,'<span style="white-space:nowrap;word-break:normal;overflow-wrap:normal">ระยะดำเนินการ</span>')}</div>`).join('')}</section>`}
function quotationSolarStamp(){return 'data:image/png;base64,'}
function quotationSignatures(preview=false,q={}){const solar=q.workType==='Solar Cell'||q.company?.taxId==='0403566004363',height=preview?'15px':'30px',line=`width:75%;max-width:${preview?'90px':'180px'};margin:0 auto;border-top:1px solid #888;padding-top:3px`;return `<section style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:${preview?'14px':'28px'};margin-top:${preview?'20px':'38px'};text-align:center;font-size:${preview?'6.5px':'10px'};line-height:1.5;break-inside:avoid;page-break-inside:avoid;color:#171717"><div><b>${q.documentKind==='RECEIPT'?'ลูกค้า / ผู้ชำระเงิน':q.documentKind==='INVOICE'?'ลูกค้า / ผู้รับเอกสาร':'ลูกค้า / ผู้อนุมัติใบเสนอราคา'}</b><div style="height:${height}"></div><div class="customer-signature-name" style="${line};min-height:1.5em;overflow-wrap:anywhere">${esc(q.customerName||'')}</div><div style="margin-top:5px;white-space:nowrap">วันที่ ${q.issueDate?esc(thaiDocumentDate(q.issueDate)):'—'}</div></div><div><b>${solar?'ห้างหุ้นส่วนจำกัด เอ็มบี โซล่า':'บริษัท / ผู้มีอำนาจลงนาม'}</b><div style="height:${height};display:flex;align-items:center;justify-content:center">${q.company?.signatureData?`<img alt="ลายเซ็นบริษัท" src="${esc(q.company.signatureData)}" style="display:block;max-width:75%;width:${preview?'85px':'170px'};height:100%;object-fit:contain">`:''}</div><div style="${line};overflow-wrap:anywhere">${esc(quotationCompany(q.company).signerName)}</div><div style="margin-top:5px;white-space:nowrap">วันที่ ${q.issueDate?esc(thaiDocumentDate(q.issueDate)):'—'}</div>${solar?`<div style="height:${preview?'30px':'60px'};display:flex;align-items:center;justify-content:center"><img alt="ตราประทับ ห้างหุ้นส่วนจำกัด เอ็มบี โซล่า" src="${quotationSolarStamp()}" style="max-width:80%;width:${preview?'80px':'160px'};max-height:100%;object-fit:contain"></div>`:''}</div></section>`}
function quotationHeader(logo,preview=false,q={}){const company=quotationCompany(q.company),solar=q.workType==='Solar Cell'||company.taxId==='0403566004363',detailStyle=`min-width:0;line-height:1.4;font-size:${preview?'6.5px':'10px'};overflow-wrap:anywhere`,field=(label,value)=>`<div><span>${label}: </span>${value}</div>`;return `<header class="quotation-parties" style="display:grid;grid-template-columns:minmax(0,35fr) minmax(0,30fr) minmax(0,35fr);align-items:start;gap:${preview?'4px':'8px'};border-bottom:3px solid #f4c400;padding-bottom:${preview?'5px':'8px'};margin-bottom:5px;color:#171717"><div class="quotation-company-block" style="${detailStyle};text-align:left"><b class="quotation-company-name" data-print-font-size="${solar?11:10}" style="display:block;max-width:100%;white-space:${solar&&!preview?'nowrap':'normal'};overflow-wrap:anywhere;font-size:${solar?(preview?'7px':'11px'):(preview?'7px':'10px')}">${esc(company.name)}</b>${field('เบอร์โทร',esc(company.phone))}${field('อีเมล',esc(company.email))}${field('เลขผู้เสียภาษี',esc(company.taxId))}${field('ที่อยู่',quotationCompanyAddress(company.address))}</div><div class="quotation-brand-heading" style="min-width:0;min-height:0;align-self:stretch;text-align:center;display:flex;flex-direction:column;align-items:center;gap:1px"><strong style="display:block;font-size:${solar?(preview?'11px':'20px'):q.documentKind==='RECEIPT'?'16px':q.documentKind==='INVOICE'?'12px':preview?'11px':'20px'};line-height:1.2;white-space:nowrap">${q.documentKind==='RECEIPT'?'ใบเสร็จรับเงิน':q.documentKind==='INVOICE'?'ใบแจ้งหนี้/ใบกำกับภาษี':'ใบเสนอราคา'}</strong><span style="display:block;font-size:${preview?'6px':'10px'};letter-spacing:${!solar&&q.documentKind==='INVOICE'?0:1}px">${q.documentKind==='RECEIPT'?'RECEIPT':q.documentKind==='INVOICE'?'Invoice / Tax Invoice':'QUOTATION'}</span>${logo?`<div class="quotation-logo-fit" style="position:relative;${solar?`flex:none;width:${preview?55:110}px;height:${preview?17:34}px;max-width:100%;align-self:center`:'flex:1;align-self:stretch;min-height:0'}"><img src="${esc(logo)}" alt="โลโก้บริษัท" style="position:absolute;inset:0;display:block;width:100%;height:100%;max-width:100%;object-fit:contain;object-position:center top"></div>`:preview?'<span style="font-size:8px;color:#777">LOGO</span>':''}</div><div class="quotation-customer-block" style="${detailStyle};text-align:right">${field('เลขที่','<b>'+esc(q.quoteNo||'ระบบสร้างอัตโนมัติ')+'</b>')}${q.documentKind==='RECEIPT'?field('เลขที่อ้างอิง IV',esc(q.referenceInvoiceNo))+field('เลขที่อ้างอิง QT',esc(q.referenceQuoteNo)):q.documentKind==='INVOICE'?field('เลขที่อ้างอิง',esc(q.referenceQuoteNo)):''}${field(q.documentKind==='RECEIPT'?'วันที่รับชำระ':'วันที่',thaiDocumentDate(q.issueDate))}${field('ชื่อลูกค้า','<b>'+esc(q.customerName||'ชื่อลูกค้า')+'</b>')}${field('เบอร์โทร',esc(q.customerPhone||'-'))}${field('เลขผู้เสียภาษี',esc(q.customerTaxId||'-'))}${field('ที่อยู่',quotationCompanyAddress(q.customerAddress)||'-')}</div></header>`}
