function displayDate(value){const s=String(value||'').trim(),ymd=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);if(ymd)return ymd[3].padStart(2,'0')+'/'+ymd[2].padStart(2,'0')+'/'+ymd[1];const dmy=s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})/);if(dmy)return dmy[1].padStart(2,'0')+'/'+dmy[2].padStart(2,'0')+'/'+dmy[3];return s||'-'}
function setStatus(text,type='') {const el=$('syncStatus');if(!el)return;el.textContent=text;el.className='sync-status '+type} function call(action,data={}){loading(true);return new Promise((resolve,reject)=>{let done=false;const timer=setTimeout(()=>{if(done)return;done=true;loading(false);setStatus('เชื่อมต่อล้มเหลว','error');reject(new Error('เซิร์ฟเวอร์ใช้เวลานานเกิน 45 วินาที กรุณาลองใหม่'))},45000),finish=(fn,value,failed=false)=>{if(done)return;done=true;clearTimeout(timer);loading(false);setStatus(failed?'เกิดข้อผิดพลาด':'บันทึกสำเร็จ',failed?'error':'');fn(value)};google.script.run.withSuccessHandler(x=>finish(resolve,x)).withFailureHandler(e=>finish(reject,new Error(e.message||e),true)).api(action,{token:S.token,...data})})} function loading(v){setStatus(v?'กำลังบันทึก...':'พร้อมใช้งาน',v?'busy':'');if(v)Swal.fire({title:'กำลังบันทึกข้อมูล...',allowOutsideClick:false,allowEscapeKey:false,showConfirmButton:false,customClass:{popup:'mb-loading',title:'mb-loading-title'},didOpen:()=>Swal.showLoading()});else if(Swal.isLoading())Swal.close()} function toast(t){setStatus('พร้อมใช้งาน');Swal.fire({toast:true,position:'top-end',icon:'success',title:t,showConfirmButton:false,timer:1800,timerProgressBar:true,background:'#fff',color:'#13231d',customClass:{popup:'mb-toast',title:'mb-toast-title',timerProgressBar:'mb-toast-progress'}})} function fireError(t){setStatus('เกิดข้อผิดพลาด','error');return Swal.fire({icon:'error',title:'ไม่สามารถทำรายการได้',text:t,confirmButtonText:'ตกลง',confirmButtonColor:'#087a55',customClass:{popup:'mb-popup',title:'mb-title',confirmButton:'mb-confirm'}})} function can(p){return(S.data.permissions||[]).includes(p)}
async function login(e){e.preventDefault();enter()} async function init(){try{localStorage.removeItem('mb_token')}catch(e){}if(S.data)enter();else fireError('ไม่พบข้อมูลเริ่มต้นจากเซิร์ฟเวอร์')} function enter(){$('auth').classList.add('hidden');$('app').classList.remove('hidden');$('userName').textContent=S.data.user.name;$('userRole').textContent='OWNER · โหมดทดสอบ';$('versionBadge').textContent='v'+(S.data.appVersion||'2.5.1');setStatus('พร้อมใช้งาน');render();showPage(S.page)} function logout(){location.reload()}
window.addEventListener('error',e=>{setStatus('JavaScript error: '+(e.message||'ไม่ทราบสาเหตุ'),'error');document.body.classList.remove('hidden')});window.addEventListener('unhandledrejection',e=>setStatus('เกิดข้อผิดพลาด: '+(e.reason?.message||e.reason||'ไม่ทราบสาเหตุ'),'error'));
const pageMeta={dashboard:['ภาพรวมกิจการ','กำไรจริงไม่รวม VAT','+ เพิ่มโปรเจกต์'],projects:['โปรเจกต์ทั้งหมด','เพิ่ม แก้ไข หรือลบโปรเจกต์','+ เพิ่มโปรเจกต์'],finance:['การเงิน','รายการรับ–จ่าย ประวัติ และปันผลหุ้นส่วน',''],documents:['เอกสาร','ใบเสนอราคา ใบแจ้งหนี้ และใบเสร็จ',''],loan:['คำนวณการผ่อน','กรอกครั้งเดียว เปรียบเทียบโปรโมชั่นทุกธนาคาร',''],settings:['ตั้งค่าระบบ','หมวดค่าใช้จ่าย ช่องทางจ่าย และผู้ใช้งาน','']};
function showPage(p){S.page=p;document.querySelectorAll('.page').forEach(x=>x.classList.add('hidden'));$('page-'+p).classList.remove('hidden');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===p));const m=pageMeta[p];$('pageTitle').textContent=m[0];$('pageSub').textContent=m[1];$('primaryBtn').textContent=m[2];$('primaryBtn').classList.toggle('hidden',p==='settings'||p==='loan'||!m[2]);if(!S.renderedPages?.[p])renderPage(p);if(p==='loan')calcLoan()}
function renderPage(p){const renderer={dashboard:renderDashboard,projects:renderProjects,finance:renderFinance,documents:renderDocuments,loan:renderLoan,settings:renderSettings}[p];if(!renderer)return;try{renderer();(S.renderedPages||(S.renderedPages={}))[p]=true}catch(e){console.error(p,e);$('page-'+p).innerHTML='<div class="card empty">แสดงผลไม่สำเร็จ กรุณาลองเปิดเมนูนี้อีกครั้ง<br><small>'+esc(e.message||e)+'</small></div>'}}
function render(){S.renderedPages={};renderPage(S.page)}


function financeChannel(name){const text=String(name||'').trim(),account=(S.data.balanceAccounts||[]).find(x=>x.name===text);if(account)return account.type;if(text.includes('เงินสด'))return'CASH';if(text.includes('บัญชีบริษัท')||text.includes('บริษัท'))return'COMPANY';return''}
function realBalanceSummary(){const accounts=(S.data.balanceAccounts||[]).map(x=>({...x,balance:Number(x.openingBalance)||0}));const find=name=>accounts.find(x=>x.name===String(name||'').trim());(S.data.income||[]).forEach(x=>{const a=find(x.account);if(a)a.balance+=Number(x.total!=null?x.total:x.amountExVat)||0});(S.data.expenses||[]).forEach(x=>{const a=find(x.paidBy);if(a)a.balance-=Number(x.total!=null?x.total:x.amountExVat)||0});(S.data.dividends||[]).forEach(x=>{const a=find(x.paidFrom);if(a)a.balance-=Number(x.amount)||0});const cash=accounts.filter(x=>x.type==='CASH').reduce((s,x)=>s+x.balance,0),company=accounts.filter(x=>x.type==='COMPANY').reduce((s,x)=>s+x.balance,0);return{accounts,CASH:cash,COMPANY:company,total:cash+company}}
function renderDashboard(){const t=S.data.totals,ps=S.data.projects,ordered=[...ps].sort((a,b)=>(Number(a.dividendPaid)>0)-(Number(b.dividendPaid)>0)),cash=realBalanceSummary(),accountRows=cash.accounts.map(a=>`<div class="balance-account-row"><span>${esc(a.name)}</span><b class="${a.balance<0?'negative':'positive'}">${money(a.balance)}</b></div>`).join('');$('page-dashboard').innerHTML=`<div class="metrics"><div class="card metric"><small>มูลค่างานรวม</small><b>${money(t.contract)}</b></div><div class="card metric"><small>รับเงินจริงก่อน VAT</small><b class="positive">${money(t.income)}</b></div><div class="card metric"><small>ต้นทุนรวม</small><b class="negative">${money(t.expenses)}</b></div><div class="card metric"><small>กำไรรวม</small><b class="${t.profit<0?'negative':'positive'}">${money(t.profit)}</b></div></div>${locationSummary(ps)}<section class="real-balance-panel"><div class="real-balance-head"><div><small>ทรัพย์สินหมุนเวียนของบริษัท</small><h3>เงินคงเหลือจริง</h3></div><b class="${cash.total<0?'negative':'positive'}">${money(cash.total)}</b></div><div class="real-balance-grid"><div class="cash"><span class="balance-icon">฿</span><div><small>เงินสดรวม</small><b class="${cash.CASH<0?'negative':'positive'}">${money(cash.CASH)}</b></div></div><div class="company"><span class="balance-icon">▣</span><div><small>บัญชีบริษัทรวม</small><b class="${cash.COMPANY<0?'negative':'positive'}">${money(cash.COMPANY)}</b></div></div></div>${accountRows?`<div class="balance-account-list">${accountRows}</div>`:''}<p>ยอดปันผลจะถูกหักออกจากบัญชีที่เลือก และไม่รวมในยอดบริษัทอีก</p></section><div class="section-head"><h3>กำไรแต่ละโปรเจกต์</h3><span class="muted">${ps.length} โปรเจกต์</span></div><div class="project-grid">${ordered.length?ordered.map(projectCard).join(''):'<div class="card empty">ยังไม่มีโปรเจกต์ เริ่มจากเพิ่มโปรเจกต์แรก</div>'}</div>`}
function projectStatus(status){const key=String(status||'PLANNING').toUpperCase(),map={PLANNING:{label:'วางแผน',cls:'planning'},ACTIVE:{label:'กำลังดำเนินงาน',cls:'active'},COMPLETED:{label:'เสร็จแล้ว',cls:'completed'}};return map[key]||{label:status||'ไม่ระบุ',cls:'other'}}
const THAI_PROVINCES=['กรุงเทพมหานคร','กระบี่','กาญจนบุรี','กาฬสินธุ์','กำแพงเพชร','ขอนแก่น','จันทบุรี','ฉะเชิงเทรา','ชลบุรี','ชัยนาท','ชัยภูมิ','ชุมพร','ตรัง','ตราด','ตาก','นครนายก','นครปฐม','นครพนม','นครราชสีมา','นครศรีธรรมราช','นครสวรรค์','นนทบุรี','นราธิวาส','น่าน','บึงกาฬ','บุรีรัมย์','ปทุมธานี','ประจวบคีรีขันธ์','ปราจีนบุรี','ปัตตานี','พระนครศรีอยุธยา','พะเยา','พังงา','พัทลุง','พิจิตร','พิษณุโลก','เพชรบุรี','เพชรบูรณ์','แพร่','ภูเก็ต','มหาสารคาม','มุกดาหาร','แม่ฮ่องสอน','ยโสธร','ยะลา','ร้อยเอ็ด','ระนอง','ระยอง','ราชบุรี','ลพบุรี','ลำปาง','ลำพูน','เลย','ศรีสะเกษ','สกลนคร','สงขลา','สตูล','สมุทรปราการ','สมุทรสงคราม','สมุทรสาคร','สระแก้ว','สระบุรี','สิงห์บุรี','สุโขทัย','สุพรรณบุรี','สุราษฎร์ธานี','สุรินทร์','หนองคาย','หนองบัวลำภู','อ่างทอง','อำนาจเจริญ','อุดรธานี','อุตรดิตถ์','อุทัยธานี','อุบลราชธานี','เชียงราย','เชียงใหม่'];
function projectMeta(p){return[p.projectType,p.province,p.siteLocation].filter(Boolean).map(esc).join(' · ')||'ยังไม่ระบุประเภทงานและสถานที่'}
function projectDuration(p){if(!p.startDate)return{label:'ยังไม่ระบุวันเริ่ม',days:null,complete:false};const start=new Date(String(p.startDate).slice(0,10)+'T00:00:00'),isComplete=String(p.status).toUpperCase()==='COMPLETED',endValue=p.deliveryDate||(isComplete?'':today());if(!endValue)return{label:'รอระบุวันส่งมอบ',days:null,complete:true};const end=new Date(String(endValue).slice(0,10)+'T00:00:00'),days=Math.max(1,Math.floor((end-start)/86400000)+1);return{label:isComplete?'ทำเสร็จภายใน':'ดำเนินงานมาแล้ว',days,complete:isComplete}}
function locationSummary(ps){const total=ps.length,counts={};ps.forEach(p=>{const key=String(p.province||'ยังไม่ระบุจังหวัด').trim()||'ยังไม่ระบุจังหวัด';counts[key]=(counts[key]||0)+1});const rows=Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'th'));return`<section class="card location-summary"><div class="location-summary-head"><div><small>สัดส่วนพื้นที่ปฏิบัติงาน</small><h3>งานแยกตามจังหวัด</h3></div><b>${total} งาน</b></div><div class="location-bars">${rows.map(([name,count])=>{const pct=total?count/total*100:0;return`<div class="location-row"><div><span>${esc(name)}</span><b>${count} งาน · ${pct.toFixed(1)}%</b></div><i><em style="width:${pct}%"></em></i></div>`}).join('')||'<div class="empty">ยังไม่มีข้อมูลพื้นที่โครงการ</div>'}</div></section>`}
function projectCard(p){const status=projectStatus(p.status),income=Math.max(0,Number(p.income)||0),expense=Math.max(0,Number(p.expenses)||0),profit=income-expense,expensePct=income?expense/income*100:(expense?100:0),expenseWidth=Math.max(0,Math.min(100,expensePct)),over=expense>income,dividend=Number(p.dividendPaid)||0;return`<article class="card dashboard-project status-card finance-progress-card ${dividend>0?'dividend-complete':''}"><div class="status-card-info"><div><h3>${esc(p.name)}</h3><small>${projectMeta(p)}</small><strong class="dashboard-contract"><small>มูลค่างาน</small><b>${money(p.contractValue)}</b></strong></div><div class="status-card-badges"><span class="project-status ${status.cls}"><i></i>${esc(status.label)}</span></div></div><div class="financial-progress"><div class="financial-progress-head"><span>รายรับจริงปัจจุบัน</span><b>${money(income)}</b></div><div class="financial-progress-track ${over?'over':''}" aria-label="รายจ่าย ${expensePct.toFixed(1)} เปอร์เซ็นต์ของรายรับ"><i class="expense" style="width:${expenseWidth}%"></i><i class="profit" style="width:${over?0:100-expenseWidth}%"></i></div><div class="financial-progress-legend"><span class="expense"><i></i><small>รายจ่ายจริง</small><b>${money(expense)}</b></span><span class="profit ${over?'negative':''}"><i></i><small>${over?'ขาดทุน':'กำไรปัจจุบัน'}</small><b>${money(Math.abs(profit))}</b></span><em>${expensePct.toFixed(1)}%</em></div></div>${dividend>0?`<div class="dividend-complete-footer"><span>✓ ปันผลเรียบร้อยแล้ว</span><b>${money(dividend)}</b></div>`:''}</article>`}
function openProjectOverview(projectId){const p=S.data.projects.find(x=>x.id===projectId);if(!p)return fireError('ไม่พบโปรเจกต์');const status=projectStatus(p.status),contract=Number(p.contractValue)||0,cost=Number(p.expenses)||0,cashProfit=Number(p.profit)||0,dividend=Number(p.dividendPaid)||0;modal('รายละเอียดโปรเจกต์',`<div class="project-overview-modal"><div class="project-overview-title"><span class="project-status ${status.cls}"><i></i>${esc(status.label)}</span><h3>${esc(p.name)}</h3><small>${esc(p.customer||'ยังไม่ระบุลูกค้า')}</small><small>${projectMeta(p)}</small></div><div class="project-overview-values"><div><small>มูลค่าโครงการ</small><b>${money(contract)}</b></div><div><small>รับเงินจริงแล้ว</small><b class="positive">${money(p.income)}</b></div><div><small>ค่าใช้จ่าย</small><b class="negative">${money(cost)}</b></div><div><small>กำไรรับ–จ่าย</small><b class="${cashProfit<0?'negative':'positive'}">${money(cashProfit)}</b></div>${dividend>0?`<div><small>ปันผลแล้ว</small><b class="negative">${money(dividend)}</b></div><div><small>กำไรหลังปันผล</small><b class="${Number(p.profitAfterDividend)<0?'negative':'positive'}">${money(p.profitAfterDividend)}</b></div>`:''}</div>${p.note?`<div class="hint"><b>หมายเหตุ</b><br>${esc(p.note)}</div>`:''}</div>`)}
function renderProjects(){$('page-projects').innerHTML=`<div class="project-grid">${S.data.projects.length?S.data.projects.map(p=>{const st=projectStatus(p.status),duration=projectDuration(p);return`<article class="card project"><div class="project-card-top"><span class="project-status ${st.cls}"><i></i>${esc(st.label)}</span><span class="duration-card ${duration.complete?'complete':''}"><small>${esc(duration.label)}</small>${duration.days!=null?`<b>${duration.days} วัน</b>`:''}</span></div><h3>${esc(p.name)}</h3><div class="muted">${esc(p.customer||'ยังไม่ระบุลูกค้า')}</div><div class="project-meta-line">${projectMeta(p)}</div><div class="numbers"><div><small>รายรับ</small><b class="positive">+${money(p.income)}</b></div><div><small>ต้นทุน</small><b class="negative">-${money(p.expenses)}</b></div><div><small>กำไร</small><b class="${p.profit<0?'negative':'positive'}">${money(p.profit)}</b></div></div><div class="project-actions"><button type="button" class="btn project-ledger-btn" onclick="openProjectTransactions('${p.id}')">รายการรับ–จ่าย</button><button type="button" class="btn secondary" onclick="openProject('${p.id}')">แก้ไขโปรเจกต์</button><button type="button" class="btn danger" onclick="removeProject('${p.id}')">ลบ</button></div></article>`}).join(''):'<div class="card empty">ยังไม่มีข้อมูล</div>'}</div>`}
function pname(id){return(S.data.projects.find(x=>x.id===id)||{}).name||'-'} function ename(id){return(S.data.employees.find(x=>x.id===id)||{}).name||'-'}
function renderFinance(){const rows=[...S.data.income.map(x=>({...x,type:'รายรับ',desc:x.description,amount:x.amountExVat})),...S.data.expenses.map(x=>({...x,type:'รายจ่าย',desc:x.description,amount:x.amountExVat}))].sort((a,b)=>String(b.date).localeCompare(String(a.date))),years=[...new Set(rows.map(x=>String(x.date||'').slice(0,4)).filter(Boolean))].sort((a,b)=>b-a),incomeTotal=rows.filter(x=>x.type==='รายรับ').reduce((s,x)=>s+Number(x.total||0),0),expenseTotal=rows.filter(x=>x.type==='รายจ่าย').reduce((s,x)=>s+Number(x.total||0),0);$('page-finance').innerHTML=`<div class="finance-tabs"><button class="active" data-ftab="transactions" onclick="showFinanceTab('transactions')">รายการรับ–จ่าย</button><button data-ftab="history" onclick="showFinanceTab('history')">ประวัติรายการ</button><button data-ftab="dividends" onclick="showFinanceTab('dividends')">ปันผลหุ้นส่วน</button><button data-ftab="balances" onclick="showFinanceTab('balances')">ตั้งค่าเงินคงเหลือ</button></div><section id="finance-transactions"><div class="card finance-entry-card"><div class="finance-entry-head"><div><b>ลงรายการรับ–จ่าย</b><small>กรอกรายการใหม่หรือวางข้อมูลหลายรายการ</small></div><button type="button" class="bulk-paste-btn" onclick="openBulkPaste()">▦ ลงแบบหลายรายการ</button></div>${batchExpenseFormHtml()}</div></section><section id="finance-history" class="hidden"><div class="section-head" style="margin-top:0"><div><h3>ประวัติรายการย้อนหลัง</h3><span class="muted"><span id="financeHistoryCount">${rows.length}</span> รายการ</span></div></div><div class="history-filters finance-history-period"><select id="financeHistoryProject" aria-label="โปรเจกต์" onchange="filterFinanceHistory()"><option value="">ทุกโปรเจกต์</option>${S.data.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><select id="financeHistoryType" aria-label="ประเภทรายการ" onchange="filterFinanceHistory()"><option value="">รวมรายรับ–รายจ่าย</option><option value="รายรับ">รายรับ</option><option value="รายจ่าย">รายจ่าย</option></select><select id="financeHistoryMonth" aria-label="เดือน" onchange="filterFinanceHistory()"><option value="">ทั้งปี / ทุกเดือน</option>${thaiMonths.map((m,i)=>`<option value="${String(i+1).padStart(2,'0')}">${m}</option>`).join('')}</select><select id="financeHistoryYear" aria-label="ปี" onchange="filterFinanceHistory()"><option value="">ทุกปี</option>${years.map(y=>`<option value="${y}">${Number(y)+543}</option>`).join('')}</select><button type="button" class="btn" onclick="exportFinanceHistory()">ส่งออก Excel</button></div><div class="metrics finance-history-summary"><div class="card metric"><small>รายรับรวม</small><b id="financeHistoryIncome" class="positive">${money(incomeTotal)}</b></div><div class="card metric"><small>รายจ่ายรวม</small><b id="financeHistoryExpense" class="negative">${money(expenseTotal)}</b></div><div class="card metric"><small>คงเหลือสุทธิ</small><b id="financeHistoryNet" class="${incomeTotal-expenseTotal<0?'negative':'positive'}">${money(incomeTotal-expenseTotal)}</b></div></div><div class="card finance-ledger"><div class="table-wrap"><table class="table"><thead><tr><th>วันที่</th><th>ประเภท</th><th>หน้างาน</th><th>รายละเอียด</th><th>ช่องทาง</th><th>ยอดเงิน</th><th>จัดการ</th></tr></thead><tbody>${rows.map(x=>`<tr class="finance-history-row ${x.type==='รายรับ'?'finance-row-income':'finance-row-expense'}" data-project="${x.projectId}" data-date="${esc(String(x.date||'').slice(0,10))}" data-type="${x.type}" data-amount="${Number(x.total||0)}"><td class="history-date">${esc(displayDate(x.date))}</td><td><span class="finance-type-badge">${x.type}</span></td><td>${esc(pname(x.projectId))}</td><td>${esc(x.desc)}</td><td>${esc(x.account||x.paidBy||'-')}</td><td><b>${x.type==='รายรับ'?'+':'−'}${money(x.total)}</b></td><td><div class="history-row-actions"><button type="button" class="history-edit-btn" onclick="loadTransactionIntoEntry('${x.type==='รายรับ'?'INCOME':'EXPENSE'}','${x.id}')">แก้ไข</button><button type="button" class="history-delete-btn" onclick="removeTransaction('${x.type==='รายรับ'?'INCOME':'EXPENSE'}','${x.id}')">ลบ</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">ยังไม่มีรายการ</td></tr>'}</tbody></table></div><div id="financeHistoryEmpty" class="empty hidden">ไม่พบรายการตามช่วงเวลาที่เลือก</div></div></section><section id="finance-dividends" class="hidden">${dividendContent()}</section><section id="finance-balances" class="hidden">${balanceSettingsContent()}</section>`}
function showFinanceTab(tab){['transactions','history','dividends','balances'].forEach(x=>$('finance-'+x).classList.toggle('hidden',x!==tab));document.querySelectorAll('[data-ftab]').forEach(x=>x.classList.toggle('active',x.dataset.ftab===tab));$('primaryBtn').classList.add('hidden')}
const QUOTE_DEFAULTS={warranty:'ตัวเครื่องชาร์จ EV รับประกันอุปกรณ์ 2 ปีเต็ม นับจากวันส่งมอบงาน\nงานติดตั้งระบบไฟฟ้าและอุปกรณ์ประกอบระบบรับประกัน 1 ปี\nบริการออนไลน์เซอร์วิส 24 ชั่วโมง\nOnsite Service ภายในไม่เกิน 3 วัน หรือ 72 ชั่วโมง',scope:'ราคานี้รวมงานติดตั้งตามรายละเอียดในใบเสนอราคา\nทางบริษัทดำเนินการยื่นเอกสารขอไฟให้ แต่ไม่รวมค่าธรรมเนียมที่หน่วยงานเรียกเก็บจริง\nพื้นที่ติดตั้งต้องมีสัญญาณอินเทอร์เน็ต 4G/Wi-Fi สำหรับระบบหลังบ้าน'};
function quotationWarrantyText(text){const value=String(text??''),legacy=QUOTE_DEFAULTS.warranty.split('\nOnsite Service')[0];return value.trim()===legacy.trim()?QUOTE_DEFAULTS.warranty:value}
function quotationTotals(q,preview=false){const grid='display:grid;grid-template-columns:5% 47% 7% 7% 16% 18%;align-items:center;',label='grid-column:5;text-align:center;white-space:nowrap;padding:2px 0;',amount='grid-column:6;text-align:center;white-space:nowrap;padding:2px 0;';return `<section style="margin-top:5px;font-size:${preview?'6.5px':'11px'};break-inside:avoid"><div style="${grid}"><span style="${label}">รวมเป็นเงิน</span><b style="${amount}">${money(q.subtotal)}</b><span style="${label}">VAT ${Number(q.vatRate)}%</span><b style="${amount}">${money(q.vatAmount)}</b></div><div style="${grid}background:#f4c400;border-top:2px solid #111;padding:4px 0"><span style="grid-column:2;text-align:center;overflow-wrap:anywhere">(${thaiBahtText(q.grandTotal)})</span><b style="${label}">ยอดสุทธิ</b><b style="${amount}">${money(q.grandTotal)}</b></div></section>`}
function quotationNote(q,preview=false){return q.note?`<div style="width:100%;text-align:left;margin:5px 0 6px;padding:0;font-size:${preview?'7px':'11px'};overflow-wrap:anywhere;color:${q.noteColor==='red'?'#c62828':'#171717'}"><b>หมายเหตุ:</b> ${nl2br(q.note)}</div>`:''}
function quotationFormDefaults(type){const saved=(S.data.quotePresets||[]).find(x=>x.kind==='TEMPLATE'&&x.workType===type);if(saved){const data=structuredClone(saved.data);if(type==='EV Charger')data.warrantyText=quotationWarrantyText(data.warrantyText);return data};return {vatRate:7,noteColor:'black',paymentTerms:type==='EV Charger'?'ชำระเงินภายใน 7 วัน นับจากวันที่ออกใบเสนอราคา':'',deliveryTerms:type==='EV Charger'?'ส่งมอบภายใน 4 เดือนหลังยืนยันใบสั่งซื้อ':'',warrantyText:type==='EV Charger'?QUOTE_DEFAULTS.warranty:'',scopeText:type==='EV Charger'?QUOTE_DEFAULTS.scope:''}}
function chooseQuotationForm(manage=false){manage=true;const forms=(S.data.quotePresets||[]).filter(x=>['TEMPLATE','FORM'].includes(x.kind));documentPanel('สร้างใบเสนอราคา / ฟอร์มที่บันทึกไว้',`<div class="saved-quote-forms"><button class="btn" onclick="openQuotation(null,'Other')">+ สร้างใบเสนอราคาเปล่า</button><button class="btn" onclick="openQuotation(null,'Other',${manage?"'FORM'":"''"})">${manage?'+ สร้างฟอร์มใหม่':'+ เริ่มใบเสนอราคาเปล่า / งานอื่น'}</button>${['EV Charger','Solar Cell'].filter(type=>!forms.some(f=>f.kind==='TEMPLATE'&&f.workType===type)).map(type=>'<button class="btn secondary" data-type="'+esc(type)+'" onclick="openQuotation(null,this.dataset.type)">ฟอร์ม '+esc(type)+'</button>').join('')}${forms.map(f=>`<article class="saved-quote-form"><div><b>${esc(f.name)}</b><small>${f.workType==='Other'?'งานทั่วไป':esc(f.workType)} · ${(f.data.items||[]).length} รายการเริ่มต้น</small></div><div><button class="btn" data-type="${esc(f.workType)}" data-id="${esc(f.id)}" onclick="openQuotation(null,this.dataset.type,'',this.dataset.id)">ใช้ฟอร์มนี้</button>${manage?`<button class="btn secondary" data-type="${esc(f.workType)}" data-id="${esc(f.id)}" data-kind="${esc(f.kind)}" onclick="openQuotation(null,this.dataset.type,this.dataset.kind,this.dataset.id)">แก้ไขฟอร์ม</button>`:''}</div></article>`).join('')}</div><div class="document-workspace-sets"><b>ชุดรายการสำเร็จรูป</b><button class="btn secondary" onclick="openQuotationSets('EV Charger')">ชุดรายการ EV</button><button class="btn secondary" onclick="openQuotationSets('Solar Cell')">ชุดรายการ Solar</button></div><p class="muted">ฟอร์มเก็บข้อมูลบริษัท รายการ ราคา และเงื่อนไข โดยไม่เก็บข้อมูลลูกค้า เลขเอกสาร หรือชื่อโครงการของใบก่อน</p>`)}
async function saveQuotationAsForm(button){const form=button.form,name=form.elements.newFormName;if(!name.value.trim()){name.setCustomValidity('กรุณาตั้งชื่อฟอร์ม');name.reportValidity();name.setCustomValidity('');name.focus();return}name.setCustomValidity('');const data=Object.fromEntries(new FormData(form));data.items=[...form.querySelectorAll('#quotationItems tr')].map(quotationRowData);data.id='';data.kind='FORM';data.name=name.value.trim();await submit('saveQuotePreset',data,'บันทึกฟอร์มแล้ว — เลือกใช้ได้จากฟอร์มที่บันทึกไว้')}
function quotationLibraryTools(){return `<section class="card document-library"><div class="document-section-heading"><b>ฟอร์มและชุดรายการสำเร็จรูป</b><small>เลือกประเภทงานเพื่อสร้างเอกสารหรือตั้งค่าฟอร์ม</small></div><div class="document-type-grid">${['EV Charger','Solar Cell'].map(type=>`<article class="document-type-card"><div><span class="document-type-label">${type==='EV Charger'?'EV':'SOLAR'}</span><h3>${type}</h3><small>ฟอร์มและชุดราคาแยกตามประเภทงาน</small></div><div class="document-type-actions"><button class="document-primary" onclick="openQuotation(null,'${type}')">+ สร้างใบเสนอราคา</button><button onclick="openQuotation(null,'${type}','TEMPLATE')">ตั้งค่าฟอร์ม</button><button onclick="openQuotationSets('${type}')">จัดการชุดรายการ</button></div></article>`).join('')}</div><p class="document-help">ตั้งค่าเงื่อนไข โลโก้ VAT และหมายเหตุได้ โดยไม่เปลี่ยนใบเสนอราคาที่บันทึกแล้ว</p></section>`}
function openQuotationSets(type){const sets=(S.data.quotePresets||[]).filter(x=>x.kind==='SET'&&x.workType===type);documentPanel('ชุดรายการ '+type,`<div class="document-set-manager"><div class="document-set-toolbar"><span>${sets.length} ชุดรายการ <small>ราคาก่อน VAT</small></span><button class="btn" onclick="openQuotation(null,'${type}','SET')">+ สร้างชุดรายการ</button></div><div class="document-set-list">${sets.map(x=>`<article class="document-set-row"><div class="document-set-info"><b>${esc(x.name)}</b><small>${(x.data.items||[]).length} รายการ</small></div><b class="document-set-price">${money((x.data.items||[]).reduce((s,i)=>s+quotationLineAmount(i),0))}</b><div class="quotation-actions"><button onclick="openQuotation(null,'${type}','SET','${x.id}')">แก้ไข</button><button class="delete" onclick="deleteQuotationSet('${x.id}')">ลบชุด</button></div></article>`).join('')||'<p class="quotation-empty">ยังไม่มีชุดรายการ กดสร้างชุดแล้วใส่รายละเอียดและราคาได้เลย</p>'}</div></div>`,'document-set-popup')}
async function deleteQuotationSet(id){const result=await Swal.fire({title:'ลบชุดรายการนี้?',text:'ใบเสนอราคาที่เคยใช้ชุดนี้จะไม่เปลี่ยนแปลง',showCancelButton:true,confirmButtonText:'ลบ',cancelButtonText:'ยกเลิก'});if(result.isConfirmed)await submit('deleteQuotePreset',{id},'ลบชุดรายการแล้ว')}
function quotationSetPicker(type){const sets=(S.data.quotePresets||[]).filter(x=>x.kind==='SET'&&x.workType===type),option=x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${money((x.data.items||[]).reduce((s,i)=>s+quotationLineAmount(i),0))}</option>`;return `<div class="field quotation-set-picker"><label>เพิ่มจากชุดรายการ ${esc(type)} (ราคาก่อน VAT)</label><div class="quotation-set-controls quotation-set-controls-simple"><select aria-label="เลือกชุดรายการ" id="quotationSetSelect"><option value="">เลือกชุดรายการ</option>${(type==='Solar Cell'?['On-grid','Hybrid On/Off-grid','อื่น ๆ'].map(group=>{const groupSets=sets.filter(x=>(x.name.startsWith('On-grid')?'On-grid':x.name.startsWith('Hybrid')?'Hybrid On/Off-grid':'อื่น ๆ')===group);return groupSets.length?'<optgroup label="'+esc(group)+'">'+groupSets.map(option).join('')+'</optgroup>':''}).join(''):sets.map(option).join(''))}</select><button type="button" class="btn secondary" onclick="insertQuotationSet()">+ เพิ่มชุด</button><button type="button" class="btn secondary" onclick="clearQuotationItems()">ล้างรายการทั้งหมด</button></div><small>${sets.length?'เพิ่มต่อท้ายรายการเดิม และแก้ไขราคาเฉพาะใบนี้ได้':'ยังไม่มีชุด — สร้างได้จากหน้ารวมใบเสนอราคา > จัดการชุดรายการ'}</small></div>`}
function filterQuotationSets(text){const needle=text.trim().toLowerCase();[...$('quotationSetSelect').options].forEach(o=>{o.hidden=!!o.value&&!o.text.toLowerCase().includes(needle)});$('quotationSetSelect').value=''}
function insertQuotationSet(){const id=$('quotationSetSelect').value,form=document.querySelector('.quotation-editor'),set=(S.data.quotePresets||[]).find(x=>x.id===id&&x.kind==='SET'&&x.workType===form.elements.workType.value);if(!set)return;const selectedItems=quotationPackageRows(set.data.items,form.elements.workType.value),body=$('quotationItems'),blank=[...body.rows].filter(row=>!row.querySelector('[data-q="description"]').value.trim()&&!Number(row.querySelector('[data-q="unitPrice"]').value));if(body.rows.length-blank.length+selectedItems.length>100)return fireError('เพิ่มได้สูงสุด 100 รายการ');blank.forEach(row=>row.remove());body.insertAdjacentHTML('beforeend',selectedItems.map(quotationItemRow).join(''));$('quotationSetSelect').value='';updateQuotationTotal();renderQuotationPreview()}
function quotationCompany(company={}){const value=Object.assign({signerName:'สุภาวดี ผาผง (กรรมการ)',name:'บริษัท โกเนกซ์ เอ็นจิเนียริ่ง กรุ๊ป จำกัด',phone:'096-1239119',email:'co.gonext@gmail.com',taxId:'0445569001456',address:'เลขที่ 80 ม.10 ต.หัวขวาง อ.โกสุมพิสัย จ.มหาสารคาม 44140',bankName:'ธนาคารกสิกรไทย',bankAccount:'236-2-83891-9',accountName:'บริษัท โกเนกซ์ เอ็นจิเนียริ่ง กรุ๊ป จำกัด'},company||{});if(String(value.address).trim()==='เลขที่ 80 ม.10 ต.หัวขวาง อ.โกสุมพิสัย จ.มหาสารคาม')value.address+=' 44140';return value}
function quotationCompanyForm(q,mode){const c=quotationCompany(q.company);return `<details class="quotation-editor-section" style="${mode==='SET'?'display:none':''}" ${mode==='TEMPLATE'?'open':''}><summary><b>ข้อมูลบริษัท / ผู้ออกเอกสาร</b> <small>กดเพื่อแก้ไข</small></summary><div class="form-grid">${[['name','ชื่อบริษัท'],['phone','เบอร์โทร'],['email','อีเมล'],['taxId','เลขผู้เสียภาษี'],['address','ที่อยู่'],['accountName','ชื่อบัญชี'],['bankName','ธนาคาร'],['bankAccount','เลขบัญชี'],['signerName','ชื่อผู้ลงนามบริษัท']].map(([k,label])=>`<div class="field ${['name','address'].includes(k)?'quotation-address':''}"><label>${label}</label><input name="company_${k}" value="${esc(c[k])}" maxlength="${k==='address'?1000:200}"></div>`).join('')}</div>${quotationSignatureUpload(c)}<small>แก้ไขเฉพาะใบนี้ได้ หากต้องการใช้กับใบใหม่ ให้บันทึกในเมนูตั้งค่าฟอร์ม</small></details>`}
function quotationCompanyFromForm(form){return Object.fromEntries(['name','phone','email','taxId','address','bankName','bankAccount','accountName','signerName','signatureData'].map(k=>[k,form.elements['company_'+k]?.value??quotationCompany()[k]??'']))}
function quotationCompanyAddress(address){return esc(String(address||'').replace(/\s+/g,' ').trim())}
function quotationSignatureUpload(c){return `<div class="field" style="margin-top:14px"><label>ภาพลายเซ็นบริษัท</label><input type="file" accept="image/png,image/jpeg,image/webp" onchange="loadQuotationSignature(this)"><input type="hidden" name="company_signatureData" value="${esc(c.signatureData||'')}"><div style="display:flex;gap:12px;align-items:center"><img id="quotationSignatureThumb" class="${c.signatureData?'':'hidden'}" src="${esc(c.signatureData||'')}" alt="ตัวอย่างลายเซ็น" style="max-width:180px;height:55px;object-fit:contain"><button type="button" class="btn secondary" onclick="clearQuotationSignature(this.form)">เอาลายเซ็นออก</button></div><small>ใช้ภาพลายเซ็นบริษัทที่คุณมีสิทธิ์ใช้ แนะนำ PNG พื้นหลังโปร่งใส · บันทึกในตั้งค่าฟอร์มเพื่อใช้กับใบใหม่</small></div>`}
function clearQuotationSignature(form){form.elements.company_signatureData.value='';const thumb=$('quotationSignatureThumb');thumb.removeAttribute('src');thumb.classList.add('hidden');renderQuotationPreview()}
function loadQuotationSignature(input){const file=input.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){input.value='';return fireError('ใช้ไฟล์ PNG, JPG หรือ WebP ขนาดไม่เกิน 8 MB')}const form=input.form,reader=new FileReader();reader.onerror=()=>fireError('อ่านไฟล์ลายเซ็นไม่สำเร็จ');reader.onload=()=>{const img=new Image();img.onerror=()=>fireError('เปิดภาพลายเซ็นไม่สำเร็จ');img.onload=()=>{if(!form.isConnected)return;let data='';for(const width of [420,320,240,180]){const scale=Math.min(1,width/img.width,160/img.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);data=canvas.toDataURL('image/webp',.85);if(data.length<=20000)break}if(data.length>20000)return fireError('ภาพมีรายละเอียดมากเกินไป กรุณาครอปให้เหลือเฉพาะลายเซ็น');form.elements.company_signatureData.value=data;const thumb=$('quotationSignatureThumb');thumb.src=data;thumb.classList.remove('hidden');renderQuotationPreview()};img.src=reader.result};reader.readAsDataURL(file)}
function fitQuotationPrint(w){const doc=w.document,content=doc.querySelector('.paper-content');if(!content)return;content.style.zoom='1';doc.querySelectorAll('.quotation-company-name').forEach(el=>{let size=Number(el.getAttribute('data-print-font-size'))||10;el.style.fontSize=size+'px';while(el.scrollWidth>el.clientWidth+1&&size>5){size-=.25;el.style.fontSize=size+'px'}});doc.querySelectorAll('.invoice-terms-line').forEach(el=>{let size=10;el.style.fontSize=size+'px';while(el.scrollWidth>el.clientWidth&&size>5){size-=.25;el.style.fontSize=size+'px'}});const footer=doc.querySelector('.paper-footer'),maxHeight=272.5*96/25.4-(footer?footer.getBoundingClientRect().height:0),height=content.getBoundingClientRect().height;content.style.zoom=String(Math.min(1,maxHeight/Math.max(height,1)));}
function quotationProjectTitle(q){if(String(q.projectName||'').trim())return 'เสนอโครงการ '+String(q.projectName).trim();if(q.workType==='Solar Cell'){const titles=(q.items||[]).map(x=>String(x.description||'').split('\n')[0]).filter(x=>x.startsWith('งานติดตั้งระบบ Solar Roof'));return titles.length?'เสนอโครงการ '+titles.join(' / '):'เสนอโครงการติดตั้งระบบ Solar Cell'}const models=new Map();(q.items||[]).forEach(item=>{const text=String(item.description||''),match=text.match(/Flexxfast[^\n]*?(\d+(?:\.\d+)?)\s*kW/i);if(!match)return;let count=0;if(text.startsWith('งานติดตั้งสถานี')){const qty=text.match(/—\s*(\d+)\s*เครื่อง/);count=qty?Number(qty[1]):0}else if(item.unit==='เครื่อง'||item.packagePrice===true)count=Number(item.quantity)||0;else if(item.unit==='ชุด'){const quantity=text.match(/จำนวน\s*(\d+)\s*เครื่อง/);if(quantity)count=Number(quantity[1])}if(count>0)models.set(match[1],(models.get(match[1])||0)+count)});return models.size?'เสนอโครงการติดตั้งเครื่องอัดประจุความเร็วสูง '+[...models].map(([kw,count])=>kw+' kW จำนวน '+count+' ตู้').join(' และ '):'รายการสินค้าและบริการที่เสนอ'}
function quotationColumns(){return '<colgroup><col style="width:5%"><col style="width:47%"><col style="width:7%"><col style="width:7%"><col style="width:16%"><col style="width:18%"></colgroup>'}
function quotationPackageRows(items,workType){if(workType&&workType!=='EV Charger')return items;const out=[];for(let i=0;i<items.length;i++){const x=items[i],match=String(x.description||'').match(/^.*Flexxfast[^\n]*?(\d+(?:\.\d+)?)\s*kW/i);if(!x.packagePrice||!match||String(x.description).startsWith('งานติดตั้งสถานี')){out.push(x);continue}const group=[x];while(items[i+1]?.packageIncluded===true)group.push(items[++i]);if(group.length===1){out.push(x);continue}out.push({description:'งานติดตั้งสถานีอัดประจุไฟฟ้าความเร็วสูง (DC Charge) ขนาด '+match[1]+' kW\nรายการย่อยที่ลูกค้าจะได้รับ\n'+group.map(item=>'• '+item.description+' — '+item.quantity+' '+item.unit).join('\n'),quantity:1,unit:'งาน',unitPrice:group.reduce((sum,item)=>sum+quotationLineAmount(item),0),packagePrice:true,packageIncluded:false})}return out.map(item=>({...item,description:String(item.description||'').replace(/IP55/g,'IP65')}))}
function quotationDescriptionHtml(x){const lines=String(x.description||'').split('\n');if(!(lines[0].startsWith('งานติดตั้งสถานี')||lines[0].startsWith('งานติดตั้งระบบ Solar Roof'))||!lines.includes('รายการย่อยที่ลูกค้าจะได้รับ'))return nl2br(x.description);return '<b>'+esc(lines[0])+'</b><div style="margin-top:4px;font-size:.95em;text-align:left">'+lines.slice(1).map(line=>'<div style="margin:0 0 2px;line-height:1.4">'+esc(line)+'</div>').join('')+'</div>'}
function quotationLineAmount(x){return Math.round(((x.packagePrice===true?Number(x.unitPrice):Number(x.quantity)*Number(x.unitPrice))+Number.EPSILON)*100)/100}
function quotationRowData(row){return {description:row.querySelector('[data-q="description"]').value,quantity:Number(row.querySelector('[data-q="quantity"]').value)||0,unit:row.querySelector('[data-q="unit"]').value,unitPrice:Number(row.querySelector('[data-q="unitPrice"]').value)||0,packagePrice:row.dataset.packagePrice==='true',packageIncluded:row.dataset.packageIncluded==='true'}}
function quotationPriceLabel(x,total=false){if(x.packagePrice&&!total)return 'เหมารวมชุด';if(x.packageIncluded&&!Number(x.unitPrice))return 'รวมในชุด';return money(total?quotationLineAmount(x):x.unitPrice)}
function quotationStatus(status){return{DRAFT:'ฉบับร่าง',SENT:'ส่งแล้ว',APPROVED:'อนุมัติแล้ว'}[status]||'ฉบับร่าง'}
function quotationTypeFolder(quotes,type){const list=quotes.filter(q=>(q.workType==='Solar Cell'?'Solar Cell':'EV Charger')===type),groups=list.reduce((o,q)=>{const key=q.customerName||'ไม่ระบุลูกค้า';(o[key]||(o[key]=[])).push(q);return o},Object.create(null)),amount=list.reduce((sum,q)=>sum+Number(q.grandTotal||0),0);return `<details class="document-folder document-worktype-folder" data-work-type="${esc(type)}"><summary><span><b>📁 ${type==='EV Charger'?'EV':'Solar Cell'}</b><small>${Object.keys(groups).length} ลูกค้า · ${list.length} ใบเสนอราคา</small></span><b>${money(amount)}</b></summary><div class="document-folder-body">${Object.entries(groups).map(([customer,list],i)=>`<details class="document-folder" ><summary><span><b>📁 ${esc(customer)}</b><small>${list.length} ใบเสนอราคา</small></span><b>${money(list.reduce((s,x)=>s+Number(x.grandTotal||0),0))}</b></summary><div class="document-folder-body">${list.map(q=>`<div class="quotation-row"><div><b>${esc(q.quoteNo)}</b><br><small>${esc(q.workType)} · ${esc(displayDate(q.issueDate))}</small></div><span class="quotation-status ${esc(q.status)}">${quotationStatus(q.status)}</span><b>${money(q.grandTotal)}</b><small>${(q.items||[]).length} รายการ</small><div class="quotation-actions">${type==='Solar Cell'?`<button onclick="openInvoice('${q.id}')">ออกใบแจ้งหนี้</button>`:''}<button onclick="printQuotation('${q.id}')">PDF / พิมพ์</button><button onclick="openQuotation('${q.id}')">แก้ไข</button><button class="delete" onclick="removeQuotation('${q.id}')">ลบ</button></div></div>`).join('')}</div></details>`).join('')||'<div class="quotation-empty">ยังไม่มีใบเสนอราคาในโฟลเดอร์นี้</div>'}</div></details>`}

function showDocumentTab(tab){S.documentTab=tab;renderDocuments()}
function renderInvoices(){const invoices=S.data.invoices||[];$('page-documents').innerHTML=`<div class="document-tabs"><button onclick="showDocumentTab('quotations')">ใบเสนอราคา</button><button class="active">ใบแจ้งหนี้ / ใบกำกับภาษี</button><button onclick="showDocumentTab('receipts')">ใบเสร็จรับเงิน</button></div><div class="card"><div class="section-head"><div><h3>ใบแจ้งหนี้ / ใบกำกับภาษี Solar Cell</h3><p>แยกงวดที่ 1 และ 2 งวดละ 50% พร้อมอ้างอิงใบเสนอราคา QT</p></div><button class="btn" onclick="openInvoice()">+ ออกใบแจ้งหนี้</button></div>${invoices.map(x=>`<div class="quotation-row"><div><b>${esc(x.invoiceNo)}</b><br><small>${esc(x.snapshot.customerName)} · ${esc(thaiDocumentDate(x.issueDate))}</small></div><span>งวดที่ ${Number(x.installment)} / 2 · 50%</span><b>${money(x.grandTotal)}</b><small>อ้างอิง ${esc(x.quoteNo)}</small><div class="quotation-actions"><button onclick="openReceipt('${x.id}')">ใบเสร็จรับเงิน</button><button onclick="printInvoice('${x.id}')">PDF / พิมพ์</button><button onclick="openInvoice('${x.quotationId}')">ดูทั้ง 2 งวด</button></div></div>`).join('')||'<div class="quotation-empty">ยังไม่มีใบแจ้งหนี้ เลือกใบเสนอราคา Solar Cell เพื่อออกเอกสาร</div>'}</div>`}
function openInvoice(quotationId){const all=S.data.invoices||[],related=all.filter(x=>x.quotationId===quotationId),q=related[0]?.snapshot||(S.data.quotations||[]).find(x=>x.id===quotationId);if(!q){const quotes=(S.data.quotations||[]).filter(x=>x.workType==='Solar Cell');return modal('เลือกใบเสนอราคา Solar Cell',`<div class="document-set-list">${quotes.map(x=>`<div class="quotation-row"><div><b>${esc(x.quoteNo)}</b><br>${esc(x.customerName)}</div><b>${money(x.grandTotal)}</b><button class="btn" onclick="openInvoice('${x.id}')">เลือก</button></div>`).join('')||'<p>กรุณาบันทึกใบเสนอราคา Solar Cell ก่อน</p>'}</div>`)}modal('ออกใบแจ้งหนี้ / ใบกำกับภาษี',`<p><b>อ้างอิง ${esc(q.quoteNo)}</b> · ${esc(q.customerName)}<br>ยอดรวม ${money(q.grandTotal)}</p>${[1,2].map(n=>{const existing=related.find(x=>Number(x.installment)===n),cents=Math.round(Number(q.grandTotal)*100),amount=(n===1?Math.round(cents/2):cents-Math.round(cents/2))/100;return `<section class="quotation-editor-section"><h4>งวดที่ ${n} · 50% · ${money(amount)}</h4><p>${n===1?'เมื่อออกใบ PO และนัดวันติดตั้ง':'หลังติดตั้งออนระบบและส่งมอบงานแล้วเสร็จ ก่อนยื่นขนานไฟจาก PEA'}</p>${existing?`<p>${esc(existing.invoiceNo)} · ${esc(thaiDocumentDate(existing.issueDate))}</p><button class="btn" onclick="printInvoice('${existing.id}')">PDF / พิมพ์</button>`:`<form onsubmit="issueInvoice(event,this)"><input type="hidden" name="quotationId" value="${esc(q.id)}"><input type="hidden" name="installment" value="${n}"><div class="form-grid"><div class="field"><label>วันที่ออกเอกสาร</label><input name="issueDate" type="date" value="${today()}" required></div></div><button class="btn" type="submit">ออกเอกสารงวดที่ ${n}</button></form>`}</section>`}).join('')}<p>ระยะดำเนินการตามตกลงของหน้างานและสัญญาโครงการ</p>`)}
async function issueInvoice(event,form){event.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;const data=Object.fromEntries(new FormData(form));try{const result=await call('createInvoice',{data});S.data={...S.data,...result};S.documentCustomer=documentArchive().records.find(r=>r.quoteId===data.quotationId)?.customerKey||'';S.documentTab='invoices';renderDocuments();openInvoice(data.quotationId);setStatus('ออกใบแจ้งหนี้แล้ว')}catch(e){fireError(e.message)}finally{button.disabled=false}}
function invoicePrintData(invoice){const source=invoice.snapshot;return {...source,documentKind:'INVOICE',quoteNo:invoice.invoiceNo,referenceQuoteNo:invoice.quoteNo,issueDate:invoice.issueDate,installment:Number(invoice.installment),subtotal:Number(invoice.subtotal),vatRate:Number(invoice.vatRate),vatAmount:Number(invoice.vatAmount),grandTotal:Number(invoice.grandTotal),items:[{description:quotationProjectTitle(source).replace(/^เสนอโครงการ/,'โครงการ')+'\n'+invoice.paymentTerms,quantity:1,unit:'งวด',unitPrice:Number(invoice.subtotal)}],paymentTerms:invoice.paymentTerms,deliveryTerms:invoice.deliveryTerms,note:'',warrantyText:'',scopeText:''}}
function printInvoice(id){const invoice=(S.data.invoices||[]).find(x=>x.id===id);if(!invoice)return fireError('ไม่พบใบแจ้งหนี้');printQuotation(null,invoicePrintData(invoice))}


function renderReceipts(){const receipts=S.data.receipts||[];$('page-documents').innerHTML=`<div class="document-tabs"><button onclick="showDocumentTab('quotations')">ใบเสนอราคา</button><button onclick="showDocumentTab('invoices')">ใบแจ้งหนี้ / ใบกำกับภาษี</button><button class="active">ใบเสร็จรับเงิน</button></div><div class="card"><div class="section-head"><div><h3>ใบเสร็จรับเงิน RECEIPT</h3><p>เลข RC ใช้ลำดับเดิมและวันที่รับชำระเงินจริง แยกตามงวด</p></div><button class="btn" onclick="openReceipt()">+ ออกใบเสร็จรับเงิน</button></div>${receipts.map(x=>`<div class="quotation-row"><div><b>${esc(x.receiptNo)}</b><br><small>${esc(x.snapshot.customerName)} · ${esc(thaiDocumentDate(x.issueDate))}</small></div><span>งวดที่ ${Number(x.installment)} / 2</span><b>${money(x.grandTotal)}</b><small>อ้างอิง ${esc(x.invoiceNo)}<br>${esc(x.quoteNo)}</small><div class="quotation-actions"><button onclick="printReceipt('${x.id}')">PDF / พิมพ์</button></div></div>`).join('')||'<div class="quotation-empty">ยังไม่มีใบเสร็จ เลือกใบแจ้งหนี้ที่ได้รับชำระแล้วเพื่อออกเอกสาร</div>'}</div>`}
function openReceipt(invoiceId){const receipts=S.data.receipts||[],existing=receipts.find(x=>x.invoiceId===invoiceId),invoice=(S.data.invoices||[]).find(x=>x.id===invoiceId);if(existing)return modal('ใบเสร็จรับเงิน',`<p><b>${esc(existing.receiptNo)}</b><br>วันที่รับชำระ ${esc(thaiDocumentDate(existing.issueDate))}<br>จำนวนเงิน ${money(existing.grandTotal)}<br>อ้างอิง ${esc(existing.invoiceNo)}</p><button class="btn" onclick="printReceipt('${existing.id}')">PDF / พิมพ์</button>`);if(!invoice){const pending=(S.data.invoices||[]).filter(x=>!receipts.some(r=>r.invoiceId===x.id));return modal('เลือกใบแจ้งหนี้ที่ได้รับชำระแล้ว',`<div class="document-set-list">${pending.map(x=>`<div class="quotation-row"><div><b>${esc(x.invoiceNo)}</b><br>${esc(x.snapshot.customerName)} · งวดที่ ${Number(x.installment)}</div><b>${money(x.grandTotal)}</b><button class="btn" onclick="openReceipt('${x.id}')">เลือก</button></div>`).join('')||'<p>ไม่มีใบแจ้งหนี้ที่รอออกใบเสร็จ</p>'}</div>`)}modal('ออกใบเสร็จรับเงิน',`<form onsubmit="issueReceipt(event,this)"><input type="hidden" name="invoiceId" value="${esc(invoice.id)}"><p><b>${esc(invoice.snapshot.customerName)}</b><br>อ้างอิง IV: ${esc(invoice.invoiceNo)}<br>อ้างอิง QT: ${esc(invoice.quoteNo)}<br>งวดที่ ${Number(invoice.installment)} · ยอดรับชำระ <b>${money(invoice.grandTotal)}</b></p><div class="field"><label>วันที่ลูกค้าชำระเงิน</label><input name="paidDate" type="date" value="${today()}" required></div><p>ยืนยันว่าได้รับชำระเงินครบตามใบแจ้งหนี้งวดนี้แล้ว</p><button class="btn" type="submit">ยืนยันรับเงินและออกใบเสร็จ</button></form>`)}
async function issueReceipt(event,form){event.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;const data={...Object.fromEntries(new FormData(form)),confirmPaid:true};try{const result=await call('createReceipt',{data});S.data={...S.data,...result};S.documentCustomer=documentArchive().records.find(r=>r.kind==='IV'&&r.id===data.invoiceId)?.customerKey||'';S.documentTab='receipts';renderDocuments();openReceipt(data.invoiceId);setStatus('ออกใบเสร็จรับเงินแล้ว')}catch(e){fireError(e.message)}finally{button.disabled=false}}
function receiptPrintData(receipt){const source=receipt.snapshot;return {...source,documentKind:'RECEIPT',quoteNo:receipt.receiptNo,referenceInvoiceNo:receipt.invoiceNo,referenceQuoteNo:receipt.quoteNo,issueDate:receipt.issueDate,installment:Number(receipt.installment),subtotal:Number(receipt.subtotal),vatRate:Number(receipt.vatRate),vatAmount:Number(receipt.vatAmount),grandTotal:Number(receipt.grandTotal),items:[{description:quotationProjectTitle(source).replace(/^เสนอโครงการ/,'โครงการ')+'\nรับชำระเงินงวดที่ '+Number(receipt.installment)+' 50% ตามใบแจ้งหนี้ '+receipt.invoiceNo,quantity:1,unit:'งวด',unitPrice:Number(receipt.subtotal)}],paymentTerms:'ได้รับชำระเงินตามใบแจ้งหนี้ '+receipt.invoiceNo+' ครบถ้วนแล้ว ณ วันที่ '+thaiDocumentDate(receipt.issueDate),deliveryTerms:'',note:'',warrantyText:'',scopeText:''}}
function printReceipt(id){const receipt=(S.data.receipts||[]).find(x=>x.id===id);if(!receipt)return fireError('ไม่พบใบเสร็จรับเงิน');printQuotation(null,receiptPrintData(receipt))}

function documentArchive(data=S.data){const quotes=data.quotations||[],invoices=data.invoices||[],receipts=data.receipts||[],quoteMap=new Map(quotes.map(x=>[x.id,x])),invoiceMap=new Map(invoices.map(x=>[x.id,x])),customers=new Map(),records=[],normalize=v=>String(v||'').trim().replace(/\s+/g,' ').toLowerCase();for(const [kind,rows] of [['QT',quotes],['IV',invoices],['RC',receipts]])for(const row of rows){const quoteId=kind==='QT'?row.id:row.quotationId||row.snapshot?.id||'',source=quoteMap.get(quoteId)||(kind==='QT'?row:invoiceMap.get(row.invoiceId)?.snapshot||row.snapshot)||{},name=String(source.customerName||'').trim()||'ไม่ระบุชื่อลูกค้า',tax=normalize(source.customerTaxId),phone=String(source.customerPhone||'').replace(/\D/g,''),key=tax?'tax:'+tax:name!=='ไม่ระบุชื่อลูกค้า'?'name:'+normalize(name)+'|'+phone:'unknown:'+quoteId,record={kind,row,id:row.id,no:String((kind==='QT'?row.quoteNo:kind==='IV'?row.invoiceNo:row.receiptNo)||''),date:String(row.issueDate||'').slice(0,10),amount:Number(row.grandTotal)||0,quoteId,customerKey:key,workType:source.workType||'Solar Cell',source};let customer=customers.get(key);if(!customer){customer={key,name,phone:source.customerPhone||'',taxId:source.customerTaxId||'',address:source.customerAddress||'',records:[]};customers.set(key,customer)}customer.records.push(record);records.push(record)}for(const customer of customers.values()){customer.records.sort((a,b)=>b.date.localeCompare(a.date)||String(b.row.createdAt||'').localeCompare(String(a.row.createdAt||''))||b.no.localeCompare(a.no));customer.latest=customer.records[0]?.date||''}return {customers:[...customers.values()].sort((a,b)=>b.latest.localeCompare(a.latest)||a.name.localeCompare(b.name,'th')),records}}
function documentMatches(record,query){return [record.no,record.row.quoteNo,record.row.invoiceNo,record.date,record.source.customerName,record.source.customerPhone,record.source.customerTaxId,record.workType,record.source.customerAddress,record.source.projectName].join(' ').toLowerCase().includes(String(query||'').trim().toLowerCase())}
function documentButton(action,id,label,style=''){return `<button type="button" class="archive-action ${style}" data-id="${esc(id)}" onclick="${action}(this.dataset.id)">${label}</button>`}
function openDocumentCustomer(key){S.documentCustomer=key;S.documentTab='all';S.documentQuery='';S.documentYear='';S.documentChain='';renderDocuments()}
